<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/CacheStore.php';require_once __DIR__.'/../core/HgdActorFetcher.php';use Core\CacheStore;use Core\DB;use Core\HgdActorFetcher;$opts=array('dry'=>false,'limit'=>0,'sleep'=>2,'quiet'=>false);$argv=isset($argv)?$argv:array();foreach(array_slice($argv,1)as $a){$a=(string)$a;if($a==='--dry'){$opts['dry']=true;}elseif($a==='--quiet'){$opts['quiet']=true;}elseif(strpos($a,'--limit=')===0){$opts['limit']=max(0,(int)substr($a,8));}elseif(strpos($a,'--sleep=')===0){$opts['sleep']=max(0,min(30,(int)substr($a,9)));}}try{$pdo=DB::pdo();$sql="SELECT id, source_id, extra FROM media_items"." WHERE source='hongguoduanju' AND type='short'"." AND (extra IS NULL OR extra='' OR extra NOT LIKE '%\"cast\"%' AND extra NOT LIKE '%\"actors\"%')"." ORDER BY id ASC";if($opts['limit']>0){$sql.=' LIMIT '.(int)$opts['limit'];}$rows=$pdo->query($sql)->fetchAll();$candidates=0;foreach($rows as $r){$ex=json_decode((string)$r['extra'],true);if(!is_array($ex)){$ex=array();}if(!empty($ex['actors'])||!empty($ex['cast'])){continue;}$candidates++;}if($candidates===0){echo($opts['quiet']?"done 0\n":"没有缺演员的短剧条目。\n");exit(0);}if($opts['dry']){printf("[dry] 待回填 %d 条（每条间隔 %d 秒，预计 %s）\n",$candidates,$opts['sleep'],gmdate('H:i:s',$candidates*$opts['sleep']));exit(0);}$upd=$pdo->prepare('UPDATE media_items SET extra=?, updated_at=NOW() WHERE id=?');$ok=0;$fail=0;$skip=0;foreach($rows as $r){$itemId=(int)$r['id'];$series=(string)$r['source_id'];$ex=json_decode((string)$r['extra'],true);if(!is_array($ex)){$ex=array();}if(!empty($ex['actors'])||!empty($ex['cast'])){$skip++;continue;}try{$actors=HgdActorFetcher::fetch($series);}catch(\Throwable $e){$fail++;if(!$opts['quiet']){fwrite(STDOUT,"  #$itemId 抓取异常：".$e->getMessage()."\n");}if($opts['sleep']>0){usleep($opts['sleep']*1000000);}continue;}if(empty($actors)){$skip++;if(!$opts['quiet']){fwrite(STDOUT,"  #$itemId 官网无演员数据\n");}if($opts['sleep']>0){usleep($opts['sleep']*1000000);}continue;}$ex['actors']=HgdActorFetcher::formatActors($actors,true);$ex['cast']=array();foreach($actors as $a){$ex['cast'][]=array('name'=>$a['name'],'character'=>$a['character'],'profile'=>'');}$upd->execute(array(json_encode($ex,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$itemId));$ok++;if(!$opts['quiet']){fwrite(STDOUT,"  #$itemId 补采 ".count($actors)." 位演员\n");}if($opts['sleep']>0){usleep($opts['sleep']*1000000);}}if($ok>0){CacheStore::invalidateTagCaches();}printf("[done] 回填 %d 条｜跳过 %d 条｜失败 %d 条\n",$ok,$skip,$fail);exit($fail>0?1:0);}catch(\Throwable $e){fwrite(STDERR,'回填失败：'.$e->getMessage()."\n");exit(1);}